function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must have the same length.';
  if (operations[0] !== 'CBTInserter' || operations.slice(1).includes('CBTInserter')) return 'Start with "CBTInserter" exactly once.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls are allowed.';
  const tree = args[0] && args[0][0];
  if (!Array.isArray(tree) || tree.length < 1 || tree.length > 1000) return 'The initial tree needs 1 to 1000 nodes.';
  if (tree.some(v => v === null)) return 'A complete tree in level order has no gaps: drop the nulls.';
  if (tree.some(v => !Number.isInteger(v) || v < 0 || v > 5000)) return 'Node values are whole numbers from 0 to 5000.';
  for (let i = 1; i < operations.length; i++) {
    if (!Array.isArray(args[i])) return 'Each call needs a list of arguments.';
    if (operations[i] === 'insert') {
      const val = args[i][0];
      if (args[i].length !== 1 || !Number.isInteger(val) || val < 0 || val > 5000) return 'insert takes one value from 0 to 5000.';
    } else if (operations[i] === 'get_root') {
      if (args[i].length !== 0) return 'get_root takes no arguments.';
    } else return `Unknown operation ${operations[i]}.`;
  }
  return null;
}

