  constructor(root) {
    this.root = root;
    this.queue = [];
    this.head = 0;
    const order = [root];
    for (let i = 0; i < order.length; i++) {
      const node = order[i];
      if (node.left) {
        order.push(node.left);
      }
      if (node.right) {
        order.push(node.right);
      }
      if (!node.left || !node.right) {
        this.queue.push(node);
      }
    }
  }

  insert(val) {
    const parent = this.queue[this.head];
    const node = new TreeNode(val);
    if (!parent.left) {
      parent.left = node;
    } else {
      parent.right = node;
      this.head++;
    }
    this.queue.push(node);
    return parent.val;
  }

  get_root() {
    return this.root;
  }
}

