function generate(rand, size) {
  const large = size === 'large';
  const pick = k => Math.floor(rand() * k);
  const value = () => large ? pick(5001) : (rand() < 0.1 ? 5000 : pick(10));
  const n = large ? 500 + pick(501) : 1 + pick(9);
  const tree = Array.from({ length: n }, value);
  const operations = ['CBTInserter'];
  const args = [[tree]];
  const calls = large ? 498 : pick(12);
  for (let c = 0; c < calls; c++) {
    const roots = large ? rand() < 0.006 : rand() < 0.2;
    if (roots) {
      operations.push('get_root');
      args.push([]);
    } else {
      operations.push('insert');
      args.push([value()]);
    }
  }
  if (!large || rand() < 0.5) {
    operations.push('get_root');
    args.push([]);
  }
  return [operations, args];
}
